using System;using System.IO;using System.Reflection;using UnityEngine;using FlyEditor.Flight;using FlyEditor.Editor;
public static class CraneAngles {
 static readonly BindingFlags H=BindingFlags.Static|BindingFlags.NonPublic;
 public static PaperInsideReverse Plan(PaperSheet s,Vector2 tip,Vector2 stop,float crease){for(int i=0;i<s.Faces.Count;i++){var f=s.Faces[i];var a=f.material.inverse.MultiplyPoint3x4(new Vector3(tip.x,0,tip.y));var b=f.material.inverse.MultiplyPoint3x4(new Vector3(stop.x,0,stop.y));if(!f.Contains(new Vector2(a.x,a.z)))continue;var p=PaperInsideReverse.Create(s,new FoldStep{insideReverse=true,cornerPull=true,packetReverse=true,compactLayers=true,anchor=i,flap=i+1,pullTip=new Vector2(a.x,a.z),pullStop=new Vector2(b.x,b.z),reverseCreaseAngle=crease});if(p!=null&&p.Pose(0)&&p.Pose(180))return p;}return null;}
 public static void Capture(PaperSheet s,string root,string name){File.WriteAllText(Path.Combine(root,name+".json"),JsonUtility.ToJson(new ResearchSave{paperFolds=s.Recipe()},true));typeof(CraneCurrentAudit).GetField("folder",H).SetValue(null,root);typeof(CraneCurrentAudit).GetMethod("Render",H).Invoke(null,new object[]{s,name,null});}
 public static void Run(){var root=Environment.GetEnvironmentVariable("FLYEDITOR_CRANE_FINISH");var recipe=JsonUtility.FromJson<ResearchSave>(File.ReadAllText(Path.Combine(root,"../.crane-current/results/10-narrow.json"))).paperFolds;
 foreach(float rootStop in new[]{3.6f,3.8f,4f}){float alpha=115;var s=PaperSheet.Replay(recipe);s.ApplyStep(new FoldStep{creaseNormal=new Vector2(1,-1),side=1,degrees=180,compactLayers=true});bool ok=true;
 for(int k=0;k<3;k++){var tip=k==1?Vector2.one*11:Vector2.zero;var stop=Vector2.one*(k==0?rootStop:k==1?11-rootStop:.65f);var p=Plan(s,tip,stop,k==1?alpha:65);Debug.Log("[Angles] angle="+alpha+" stage="+k+" plan="+(p!=null));if(p==null){ok=false;break;}for(int a=0;a<=180;a+=5)if(!p.Pose(a)){Debug.Log("[Angles] sweep fail="+a);ok=false;break;}if(!ok||!s.FinishReverse(p,180)){ok=false;break;}PacketFoldingVerification.Metrics(s);PetalFoldingVerification.Replay(s);}
 if(!ok)continue;Capture(s,root,"angles-root-"+rootStop);for(int n=0;n<1;n++){float h=5.5f;Debug.Log("[Angles] wing hinge="+h);if(!WingSearch.Wing(s,new Vector2(0,11),h,out var one)||!WingSearch.Wing(one,new Vector2(11,0),h,out var both))continue;PacketFoldingVerification.Metrics(both);PetalFoldingVerification.Replay(both);Capture(both,root,"wings-root-"+rootStop);Debug.Log("[Angles] success angle="+alpha+" hinge="+h);break;}}
 }
}
